mapper.select:
SELECT id, user_id, initiator_id, type, tenant_key, reason, expires_at, created_at, updated_at, created_by, updated_by
FROM public.bans
WHERE id = #{id}

SELECT id, user_id, initiator_id, type, tenant_key, reason, expires_at, created_at, updated_at, created_by, updated_by
FROM public.bans
WHERE user_id = #{userId}

SELECT id, user_id, initiator_id, type, tenant_key, reason, expires_at, created_at, updated_at, created_by, updated_by
FROM public.bans
WHERE tenant_key = #{tenantKey}

mapper.delete:
DELETE FROM public.bans
WHERE user_id = #{userId}
AND type = #{type, typeHandler=org.apache.ibatis.type.EnumTypeHandler}


        AND tenant_key = #{tenantKey}


        AND tenant_key IS NULL
